}
/* Expands the hotspot area. */
:scope .range-select:before {
  content: "";
  position: absolute;
  width: 100%;
  height: var(--thumb-size);
  left: 0;
  top: calc(2px - var(--thumb-radius));
}
:scope .range-select:focus,
:scope .thumb:focus {
  outline: none;
}
:scope .thumb {
  box-sizing: border-box;
  position: absolute;
  width: var(--thumb-size);
  height: var(--thumb-size);

  background: #fcfcfc;
  top: -4px;
  border-radius: 100%;
  border: 1px solid hsl(0,0%,55%);
  cursor: default;
  margin: 0;
}
:scope .thumb:active {
  box-shadow: inset 0 var(--thumb-size) #0002;
}
:scope .thumb-min {
  left: calc(-1px - var(--thumb-radius));
}
:scope .thumb-max {
  right: calc(-1px - var(--thumb-radius));
}
`



















































function lgamma(z) {
  const g = [676.5203681218851, -1259.1392167224028, 771.32342877765313,
             -176.61502916214059, 12.507343278686905, -0.13857109526572012,
             9.9843695780195716e-6, 1.5056327351493116e-7];
  if (z &lt; 0.5) return Math.log(Math.PI / Math.sin(Math.PI * z)) - lgamma(1 - z);
  z -= 1;
  let x = 0.99999999999980993;
  for (let i = 0; i &lt; g.length; i++) x += g[i] / (z + i + 1);
  const t = z + g.length - 0.5;
  return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(x);
}

function betacf(x, a, b) {
  const MAXIT = 200, EPS = 3e-12, FPMIN = 1e-300;
  const qab = a + b, qap = a + 1, qam = a - 1;
  let c = 1, d = 1 - qab * x / qap;
  if (Math.abs(d) &lt; FPMIN) d = FPMIN;
  d = 1 / d;
  let h = d;
  for (let m = 1; m &lt;= MAXIT; m++) {
    const m2 = 2 * m;
    let aa = m * (b - m) * x / ((qam + m2) * (a + m2));
    d = 1 + aa * d; if (Math.abs(d) &lt; FPMIN) d = FPMIN;
    c = 1 + aa / c; if (Math.abs(c) &lt; FPMIN) c = FPMIN;
    d = 1 / d; h *= d * c;
    aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2));
    d = 1 + aa * d; if (Math.abs(d) &lt; FPMIN) d = FPMIN;
    c = 1 + aa / c; if (Math.abs(c) &lt; FPMIN) c = FPMIN;
    d = 1 / d;
    const del = d * c;
    h *= del;
    if (Math.abs(del - 1) &lt; EPS) break;
  }
  return h;
}

function incBeta(x, a, b) {
  if (x &lt;= 0) return 0;
  if (x &gt;= 1) return 1;
  const bt = Math.exp(lgamma(a + b) - lgamma(a) - lgamma(b) +
                      a * Math.log(x) + b * Math.log(1 - x));
  return x &lt; (a + 1) / (a + b + 2)
    ? bt * betacf(x, a, b) / a
    : 1 - bt * betacf(1 - x, b, a) / b;
}

function betaQuantile(p, a, b) {
  let lo = 0, hi = 1;
  for (let i = 0; i &lt; 80; i++) {
    const mid = (lo + hi) / 2;
    if (incBeta(mid, a, b) &lt; p) lo = mid; else hi = mid;
  }
  return (lo + hi) / 2;
}

// 95% credible interval for x successes of n (Jeffreys prior), as in the app
function bayesCI(x, n) {
  if (n === 0) return [NaN, NaN];
  return [betaQuantile(0.025, x + 0.5, n - x + 0.5),
          betaQuantile(0.975, x + 0.5, n - x + 0.5)];
}





































STEP_MS = 25

function trialRT(t0, runs) {
  // keep only samples at t &gt;= 0, requiring a sample at exactly t = 0
  if (t0 &gt; 0) return null; // no data at 0
  let skip = (0 - t0) / STEP_MS; // samples to drop before t = 0
  const post = [];
  for (const [aoi, len] of runs) {
    if (skip &gt;= len) { skip -= len; continue; }
    post.push([aoi, len - skip]);
    skip = 0;
  }
  if (post.length === 0) return null; // no data at 0
  const onset = post[0][0];
  if (onset !== 0 && onset !== 1) return ({ rt: null, shift_type: "other" });
  let landingIdx = -1;
  for (let i = 1; i &lt; post.length; i++) {
    const v = post[i][0];
    if (v !== onset && (v === 0 || v === 1)) { landingIdx = i; break; }
  }
  if (landingIdx === -1) return ({ rt: null, shift_type: "no shift" });
  const landing = post[landingIdx][0];
  const shift_type =
    onset === 1 && landing === 0 ? "D-T" :
    onset === 0 && landing === 1 ? "T-D" : "other";
  let before = 0;
  for (let i = 0; i &lt; landingIdx; i++) before += post[i][1];
  return ({
    rt: (before + 1) * STEP_MS,           // landing-time RT
    shift_start_rt: (post[0][1] + 1) * STEP_MS,
    shift_type,
  });
}
















function makeAgeBinner(ages, nbins) {
  if (nbins &lt;= 1 || ages.length === 0) {
    return ({ bin: () =&gt; 0, labels: ["all ages"] });
  }
  const lo = Math.floor(Math.min(...ages));
  const hi = Math.ceil(Math.max(...ages));
  const w = Math.max(1, Math.ceil((hi - lo) / nbins));
  const n = Math.max(1, Math.ceil((hi - lo) / w));
  const labels = Array.from({ length: n }, (_, i) =&gt;
    `(${lo + i * w},${lo + (i + 1) * w}]`);
  return ({
    bin: (a) =&gt; Math.min(n - 1, Math.max(0, Math.ceil((a - lo) / w) - 1)),
    labels,
  });
}

// age-bin labels restricted to those present in the data, in bin order
// (string sorts put (12,15] before (6,9]; use this for scale domains)
function orderedBins(labels, data, field = "age_bin") {
  const present = new Set(data.map((d) =&gt; d[field]));
  return labels.filter((l) =&gt; present.has(l));
}

aoiNames = ["target", "distractor", "other", "missing"]























DATA_BASE = (typeof window !== "undefined" && window.PEEKBANK_DATA_BASE) || "slices/"

manifest = d3.json(`${DATA_BASE}manifest.json`)
datasetNames = manifest.datasets.map((d) =&gt; d.name)

// display datasets by citation (team preference), disambiguating
// duplicate shortcites with the internal name; data tables and legends
// keep the internal dataset_name, which is the key peekbankr users need
datasetLabel = {
  const counts = d3.rollup(manifest.datasets, (v) =&gt; v.length,
    (d) =&gt; d.shortcite ?? d.name);
  const m = new Map(manifest.datasets.map((d) =&gt; {
    const cite = d.shortcite ?? d.name;
    return [d.name, counts.get(cite) &gt; 1 ? `${cite} · ${d.name}` : cite];
  }));
  return (name) =&gt; m.get(name) ?? name;
}

sliceCache = new Map()

async function loadSlice(name) {
  if (!sliceCache.has(name)) {
    sliceCache.set(name, await d3.json(`${DATA_BASE}datasets/${name}.json`));
  }
  return sliceCache.get(name);
}

// flatten selected slices into one row per trial administration:
// {dataset, aid, tid, t0, runs, age, subject, word, distractor, vanilla,
//  excluded, trial_order}
function buildRows(slices, opts = {}) {
  const {
    ageLo = 0, ageHi = 999, words = null, includeExcluded = true,
    collapseWords = false,
  } = opts;
  const wordSet = words ? new Set(words) : null;
  const rows = [];
  for (const s of slices) {
    const adminById = new Map(s.admins.map((a) =&gt; [a[0], a]));
    const ttById = new Map(s.trial_types.map((t) =&gt; [t[0], t]));
    const trialById = new Map(s.trials.map((t) =&gt; [t[0], t]));
    for (const [aid, tid, t0, runs] of s.runs) {
      const admin = adminById.get(aid);
      if (!admin || admin[1] == null || admin[1] &lt; ageLo || admin[1] &gt; ageHi) continue;
      const trial = trialById.get(tid);
      if (!trial) continue;
      if (!includeExcluded && trial[3] === 1) continue;
      const tt = ttById.get(trial[2]);
      if (!tt) continue;
      if (wordSet && !wordSet.has(tt[1])) continue;
      rows.push({
        dataset: s.dataset.name, aid, tid, t0, runs,
        age: admin[1], subject: admin[2],
        word: collapseWords ? "All" : tt[1], distractor: tt[2],
        vanilla: tt[4] === 1, excluded: trial[3] === 1,
        trial_order: trial[1],
      });
    }
  }
  return rows;
}

// mean accuracy within [wLo, wHi] for one trial's runs (or null if no
// target/distractor samples in the window)
function windowAccuracy(t0, runs, wLo, wHi) {
  let t = t0, n = 0, p = 0;
  for (const [aoi, len] of runs) {
    for (let k = 0; k &lt; len; k++, t += STEP_MS) {
      if (t &lt; wLo || t &gt; wHi || aoi &gt; 1) continue;
      n += 1;
      if (aoi === 0) p += 1;
    }
  }
  return n &gt; 0 ? p / n : null;
}

wordsOf = (slices) =&gt; {
  const w = new Set();
  for (const s of slices) for (const tt of s.trial_types) {
    if (tt[1] != null) w.add(tt[1]);
  }
  return Array.from(w).sort();
}
































































