  `;

  const $range = rangeInput({min, max, value: [value[0], value[1]], step, color, width, theme});
  const $output = ihtml`&lt;output&gt;`;
  const $view = ihtml`&lt;div id=${__ns__}&gt;
${label == null ? '' : ihtml`&lt;div class="label"&gt;${label}`}
&lt;div class=form&gt;
