pearsonR = {
  const xs = pairedData.map((d) =&gt; d.lwl);
  const ys = pairedData.map((d) =&gt; d.cdi);
  const mx = d3.mean(xs);
  const my = d3.mean(ys);
  let sxy = 0;
  let sxx = 0;
  let syy = 0;
  for (let i = 0; i &lt; xs.length; i++) {
    sxy += (xs[i] - mx) * (ys[i] - my);
    sxx += (xs[i] - mx) ** 2;
    syy += (ys[i] - my) ** 2;
  }
  return sxx &gt; 0 && syy &gt; 0 ? sxy / Math.sqrt(sxx * syy) : NaN;
}












































